      <select class="select select-xs select-bordered max-w-[130px] font-mono text-warning"
        :value="compareBranch"
        @change="onCompareBranchChange">
        <option v-for="b in allCompareBranches" :key="b" :value="b">{{ b }}</option>
      </select>
    </div>

    <div class="grow"></div>

    <!-- Layout toggles -->
    <div class="join">
      <button
        class="join-item btn btn-xs"
        :class="showChat ? 'btn-primary' : 'btn-ghost'"
